def clean(m):
 m=(m or "").lower();m=re.sub(r"(make|banao|banana|create|build|python code|code|well|animated|that|open in browser|browser me|ke bare me|about|tell me|batao|kya hai|what is|who is|explain|samjhao|please|plz)"," ",m);m=re.sub(r"[^a-zA-Z0-9 ]"," ",m)
 return " ".join([w for w in m.split() if w not in STOP and len(w)>1])
def extract_topic(m):
 t=clean(m);t=re.sub(r"\b(kya|hai|kaun|kab|kahan|kyu|why|what|when|where|who|how|kaise|matlab|meaning|batao|explain)\b"," ",t);t=" ".join(t.split()).strip()
 return t or MEMORY.get("last_topic","")
