def wiki(q):
 if not q:return None
 for query in [q,q.split()[0] if q.split() else q]:
  try:
   u="https://en.wikipedia.org/api/rest_v1/page/summary/"+urllib.parse.quote(query);req=urllib.request.Request(u,headers={"User-Agent":"JARVIS"})
   with urllib.request.urlopen(req,timeout=8) as r:
    d=json.loads(r.read().decode())
    if d.get("extract"):return d["extract"][:1500]
  except:pass
 return None
def duck(q):
 if not q:return None
 try:
  u="https://api.duckduckgo.com/?q="+urllib.parse.quote(q)+"&format=json&no_html=1&skip_disambig=1";req=urllib.request.Request(u,headers={"User-Agent":"Mozilla/5.0"})
  with urllib.request.urlopen(req,timeout=8) as r:
   d=json.loads(r.read().decode());a=d.get("AbstractText") or d.get("Answer") or ""
   if a:return a[:1500]
   for t in d.get("RelatedTopics",[]):
    if isinstance(t,dict) and t.get("Text"):return t["Text"][:1500]
 except:pass
 return None
def calc_smart(e):
 try:
  e=(e or "").lower();e=e.replace("plus","+").replace("add","+").replace("jod","+").replace("minus","-").replace("ghat","-").replace("multiply","*").replace("gunna","*").replace("into","*").replace("divide","/").replace("bhag","/").replace("x","*").replace("X","*").replace("^","**").replace("÷","/").replace("×","*");e=re.sub(r"[^0-9+\-*/().\s%**]"," ",e);e=" ".join(e.split()).strip()
  if not re.match(r'^[0-9+\-*/().\s%]+$',e):return None
  if not any(c.isdigit() for c in e):return None
  val=eval(e,{"__builtins__":{}},{})
  if isinstance(val,float):val=round(val,2)
  return str(val),e
 except:return None
