 try:
  msg=(msg or "").strip()[:2000]
  if not msg:return "Dev Sir, kuch likho to sahi."
  if len(msg.split())<=3 and MEMORY.get("last_intent") in ["code","info"] and MEMORY.get("last_topic"):
   if msg.lower() in ["haan","ha","yes","ok","okay","batao","bana do","de do"]:
    return brain("simple wala bana do "+MEMORY.get("last_topic",""),lang) or brain(msg,lang)
  b=brain(msg,lang)
  if b:MEMORY["last_reply"]=b;return b
  topic=clean(msg);info=wiki(topic) or duck(topic)
  if info:return f"Dev Sir, '{topic}' ke baare me:\n\n{smart_summary(info,topic)}"
  return f"Dev Sir, samajh gaya - tum '{topic or msg}' ki baat kar rahe ho. Thoda aur detail do, main full jawab dunga."
 except Exception as e:return f"Dev Sir, thodi problem aa gayi, phir se bolo. ({e})"
