HTML+='function typewriter(span,txt,replyTs){if(typingTimer)cancelAnimationFrame(typingTimer);typingTimer=null;let total=txt.length;let dur=Math.min(2200,Math.max(600,total*8));let start=null;let textNode=document.createTextNode("");let cur=document.createElement("span");cur.className="tw-cursor";span.innerHTML="";span.appendChild(textNode);span.appendChild(cur);let lastScroll=0;function frame(ts){if(!start)start=ts;let p=Math.min(1,(ts-start)/dur);let eased=1-Math.pow(1-p,2);let n=Math.floor(eased*total);let shown=txt.slice(0,n);if(textNode.data!==shown)textNode.data=shown;if(ts-lastScroll>120){chat.scrollTop=chat.scrollHeight;lastScroll=ts;}if(p<1){typingTimer=requestAnimationFrame(frame);}else{textNode.data=txt;if(cur.parentNode)cur.remove();if(curId){let c=allChats.find(x=>x.id===curId);if(c){c.msgs.push({text:txt,w:"jarvis",ts:replyTs});c.time=Date.now();saveChats();renderList();}}chat.scrollTop=chat.scrollHeight;showChips(txt);}}typingTimer=requestAnimationFrame(frame);}'
